    'passport_open_hint': {'en': 'Swipe to open', 'te': 'తెరవడానికి స్వైప్ చేయండి', 'hi': 'खोलने के लिए स्वाइप करें', 'ta': 'திறக்க ஸ்வைப் செய்யவும்', 'kn': 'ತೆರೆಯಲು ಸ್ವೈಪ್ ಮಾಡಿ'},
    'page': {'en': 'Page', 'te': 'పేజీ', 'hi': 'पृष्ठ', 'ta': 'பக்கம்', 'kn': 'ಪುಟ'},
